// The web host's build (docs/mcp-apps.md C9, piece 11): src/views/web.ts alone, no React, into
// ../../kit/views/web.js + web.css, the files the hub's page `GET /v/<agent>/<call>` loads
// (mcp-apps-sandbox's). Committed like kit's other built files (packaging copies kit/ whole);
// `pnpm build:views-web` writes them; `pnpm build` runs scripts/views-web.mts --check, red when
// they differ. Each file starts with a 'generated by' banner (tests/js_guard.py).
import { resolve } from 'node:path';
import { defineConfig } from 'vite';

export default defineConfig({
  resolve: { alias: { '@': resolve(__dirname, 'src') } },
  build: {
    outDir: resolve(__dirname, '../../kit/views'),
    emptyOutDir: true,
    minify: true,
    sourcemap: false,
    cssCodeSplit: false,
    rollupOptions: { output: { banner: '/* generated by apps/desktop/views.web.vite.config.ts from src/views/web.ts (pnpm -C apps/desktop build:views-web), never hand-edited */' } },
    lib: { entry: resolve(__dirname, 'src/views/web.ts'), formats: ['iife'], name: 'biseView', fileName: () => 'web.js', cssFileName: 'web' },
  },
});
